// Regression test for: Applying coupon returns HTTP 500 and failure is not shown to the user
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #6.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("applying coupon SAVE10 either applies a discount or shows an error message", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  // Build the cart through the UI: Dot Grid Notebook, Desk Lamp, and 3 Ceramic Mugs (total $90.00).
  await page.goto("/product/notebook");
  await page.getByRole("button", { name: "Add to cart" }).click();
  await page.goto("/product/lamp");
  await page.getByRole("button", { name: "Add to cart" }).click();
  await page.goto("/product/mug");
  await page.getByRole("button", { name: "Add to cart" }).click();

  await page.goto("/cart");
  await expect(page.getByRole("heading", { name: "Cart", level: 1 })).toBeVisible();
  const mugQty = page.getByRole("spinbutton", { name: "Quantity of Ceramic Mug" });
  await mugQty.fill("3");
  await mugQty.blur();
  await expect(page.getByRole("heading", { name: "Total: $90.00" })).toBeVisible();

  await page.getByRole("textbox", { name: "Coupon code" }).fill("SAVE10");

  const couponResponse = page.waitForResponse((r) => r.url().includes("/api/coupon"));
  await page.getByRole("button", { name: "Apply" }).click();
  await couponResponse;

  // The user must get either a discount or a visible message explaining the failure.
  const totalHeading = page.getByRole("heading", { name: /^Total:/ });
  const feedback = page.getByText(/discount|coupon (applied|invalid|not)|invalid coupon|could not|couldn't|error|applied/i);

  await expect
    .poll(async () => {
      const totalText = (await totalHeading.textContent()) ?? "";
      const totalChanged = totalText.trim() !== "Total: $90.00";
      const messageShown = (await feedback.count()) > 0 && (await feedback.first().isVisible());
      return totalChanged || messageShown;
    })
    .toBe(true);

  expect(pageErrors).toEqual([]);
});
